"use strict";

import React, { useMemo, useState } from "react";
import { useNavigate } from "react-router-dom";
import { useAuth } from "../context/AuthContext";

const GOLD = "#ffd400";
const GOLD_GRADIENT = "linear-gradient(90deg, #F7D774 0%, #D4AF37 50%, #B8860B 100%)";
const PARTNER_HERO_IMAGE = "https://images.pexels.com/photos/4161612/pexels-photo-4161612.jpeg?auto=compress&cs=tinysrgb&w=2000";
const PARTNER_BOTTOM_BANNER_IMAGE = "data:image/png;base64,";
const PARTNER_HERO_REFERENCE_IMAGE = "data:image/png;base64,";

const BRAND_LOGO_DATA_URI = "data:image/png;base64,";

const INITIAL_FORM = {
  companyName: "",
  managerName: "",
  phone: "",
  region: "",
  businessType: "",
  budget: "",
  message: "",
};

const REGION_OPTIONS = [
  "서울",
  "경기",
  "인천",
  "부산",
  "대구",
  "광주",
  "대전",
  "울산",
  "세종",
  "경남",
  "경북",
  "전남",
  "전북",
  "충남",
  "충북",
  "강원",
  "제주",
];

const BUSINESS_OPTIONS = [
  "마사지",
  "노래방",
];


function Icon({ name, size = 22 }) {
  const common = {
    width: size,
    height: size,
    viewBox: "0 0 24 24",
    fill: "none",
    stroke: "currentColor",
    strokeWidth: 1.8,
    strokeLinecap: "round",
    strokeLinejoin: "round",
    "aria-hidden": "true",
  };

  switch (name) {
    case "bolt":
      return (
        <svg {...common}>
          <path d="m13 2-7 11h6l-1 9 7-12h-6l1-8Z" />
        </svg>
      );
    case "diamond":
      return (
        <svg {...common}>
          <path d="M3.5 8 7 3.8h10L20.5 8 12 20 3.5 8Z" />
          <path d="M3.5 8h17M8.5 8 12 20 15.5 8M7 3.8 8.5 8M17 3.8 15.5 8" />
        </svg>
      );
    case "chart":
      return (
        <svg {...common}>
          <path d="M4 20V10M10 20V4M16 20v-7M22 20V7" />
        </svg>
      );
    case "star":
      return (
        <svg {...common}>
          <path d="m12 3 2.8 5.8 6.2.9-4.5 4.4 1.1 6.2-5.6-3-5.6 3 1.1-6.2L3 9.7l6.2-.9L12 3Z" />
        </svg>
      );
    case "building":
      return (
        <svg {...common}>
          <path d="M5 21V4h10v17M15 9h4v12M8 8h4M8 12h4M8 16h4M18 13h1M18 17h1M3 21h18" />
        </svg>
      );
    case "user":
      return (
        <svg {...common}>
          <circle cx="12" cy="8" r="3.2" />
          <path d="M5 21c0-4.2 2.9-7 7-7s7 2.8 7 7" />
        </svg>
      );
    case "phone":
      return (
        <svg {...common}>
          <path d="M7.2 3.5 10 7l-2.1 2.2c1.1 2.3 2.8 4 5.1 5.1l2.2-2.1 3.5 2.8c.6.5.8 1.3.4 2-1 2-2.7 3-4.7 2.8C9.1 19.2 4.8 14.9 4.2 9.6 4 7.6 5 5.9 7 4.9c.7-.4 1.5-.2 2 .4Z" />
        </svg>
      );
    case "pin":
      return (
        <svg {...common}>
          <path d="M20 10c0 5-8 11-8 11S4 15 4 10a8 8 0 1 1 16 0Z" />
          <circle cx="12" cy="10" r="2.2" />
        </svg>
      );
    case "tag":
      return (
        <svg {...common}>
          <path d="M3 12V5a2 2 0 0 1 2-2h7l9 9-9 9-9-9Z" />
          <circle cx="8" cy="8" r="1" />
        </svg>
      );
    case "calendar":
      return (
        <svg {...common}>
          <rect x="3" y="5" width="18" height="16" rx="2" />
          <path d="M8 3v4M16 3v4M3 10h18" />
        </svg>
      );
    case "file":
      return (
        <svg {...common}>
          <path d="M6 2h8l4 4v16H6V2Z" />
          <path d="M14 2v5h5M9 12h6M9 16h6" />
        </svg>
      );
    case "send":
      return (
        <svg {...common}>
          <path d="m22 2-7 20-4-9-9-4 20-7Z" />
          <path d="M22 2 11 13" />
        </svg>
      );
    case "check":
      return (
        <svg {...common}>
          <circle cx="12" cy="12" r="9" />
          <path d="m8 12 2.7 2.7L16.5 9" />
        </svg>
      );
    case "headset":
      return (
        <svg {...common}>
          <path d="M4 13v-2a8 8 0 0 1 16 0v2" />
          <path d="M4 13h3v6H5a1 1 0 0 1-1-1v-5ZM20 13h-3v6h2a1 1 0 0 0 1-1v-5ZM17 19c0 2-1.8 3-5 3" />
        </svg>
      );
    case "handshake":
      return (
        <svg {...common}>
          <path d="m8.5 11 2.2-2.2a2 2 0 0 1 2.8 0l2 2" />
          <path d="m4 8 4.8-4 3.1 2.2M20 8l-4.8-4-3.3 2.2" />
          <path d="m4 8-2 3 5.5 6.5a2 2 0 0 0 2.8.2l1-1" />
          <path d="m20 8 2 3-6.1 7.2a2 2 0 0 1-2.8.2l-4.6-4.6" />
        </svg>
      );
    default:
      return null;
  }
}

function PartnerInquiryPage() {
  const navigate = useNavigate();
  const { isAuthenticated, setToken, setUser } = useAuth();
  const [form, setForm] = useState(INITIAL_FORM);
  const [notice, setNotice] = useState("");
  const [noticeType, setNoticeType] = useState("");

  const isFormReady = useMemo(() => {
    return Boolean(
      form.companyName.trim() &&
        form.managerName.trim() &&
        form.phone.trim() &&
        form.message.trim()
    );
  }, [form]);

  const updateField = (key, value) => {
    setForm((prev) => ({ ...prev, [key]: value }));
    if (notice) {
      setNotice("");
      setNoticeType("");
    }
  };

  const handleHeaderLogout = () => {
    try {
      localStorage.setItem("nora_user_logged_out", "true");
      sessionStorage.setItem("nora_user_logged_out", "true");
    } catch (e) {
      console.warn("PARTNER AUTH LOGOUT MARKER SAVE FAIL:", e?.message || e);
    }

    ["token", "accessToken", "authToken", "jwt", "user"].forEach((key) => {
      try {
        localStorage.removeItem(key);
        sessionStorage.removeItem(key);
      } catch (e) {
        console.warn("PARTNER AUTH STORAGE CLEAR FAIL:", key, e?.message || e);
      }
    });

    setToken("");
    setUser(null);

    try {
      window.dispatchEvent(new Event("auth-updated"));
    } catch (e) {
      console.warn("PARTNER AUTH LOGOUT EVENT FAIL:", e?.message || e);
    }

    window.location.replace("/");
  };

  const handleHeaderLoginButton = () => {
    if (isAuthenticated) {
      handleHeaderLogout();
      return;
    }

    navigate("/login");
  };

  const handleSubmit = (event) => {
    event.preventDefault();

    if (!isFormReady) {
      setNoticeType("error");
      setNotice("필수 항목을 모두 입력해주세요.");
      return;
    }

    setNoticeType("info");
    setNotice("문의 내용 작성이 완료되었습니다. 현재 페이지는 디자인 단계이며 서버 접수 API는 연결하지 않았습니다.");
  };

  const handleReset = () => {
    setForm(INITIAL_FORM);
    setNotice("");
    setNoticeType("");
  };

  const scrollToInquiryForm = () => {
    const target = document.getElementById("nora-partner-form");
    if (!target) return;
    target.scrollIntoView({ behavior: "smooth", block: "center" });
    window.setTimeout(() => {
      target.querySelector("input")?.focus({ preventScroll: true });
    }, 350);
  };

  const handleInquiryList = () => {
    scrollToInquiryForm();
    setNoticeType("info");
    setNotice("문의 내역 확인 기능은 로그인 계정 연동 후 제공됩니다.");
  };
  return (
    <div className="nora-partner-root" style={styles.page}>
      <style>{PARTNER_RESPONSIVE_CSS}</style>

      <header className="nora-jobs-page-header" style={styles.header}>
        <button
          type="button"
          onClick={() => navigate("/")}
          style={styles.logo}
          aria-label="노라 메인으로 이동"
        >
          <img
            src={BRAND_LOGO_DATA_URI}
            alt="노라 NORA 로고"
            style={styles.logoImage}
          />
        </button>

        <nav className="nora-jobs-page-nav" style={styles.nav}>
          <button type="button" onClick={() => navigate("/massage/map")} style={styles.navButton}>
            ♨ 마사지
          </button>
          <button type="button" onClick={() => navigate("/karaoke/map")} style={styles.navButton}>
            ♫ 노래방
          </button>
          <button type="button" onClick={() => navigate("/jobs")} style={styles.navButton}>
            ▣ 채용정보
          </button>
          <button type="button" onClick={() => navigate("/community")} style={styles.navButton}>
            커뮤니티
          </button>
          <button type="button" onClick={handleHeaderLoginButton} style={styles.navButton}>
            {isAuthenticated ? "로그아웃" : "회원가입/로그인"}
          </button>
          <button
            type="button"
            onClick={() => navigate("/partner-inquiry")}
            style={{ ...styles.navButton, ...styles.activeNavButton }}
          >
            제휴문의
          </button>
          <button
            type="button"
            onClick={() => navigate("/mypage")}
            style={styles.profileNavButton}
            aria-label="프로필"
            title="프로필"
          >
            <span style={styles.profileHead} />
            <span style={styles.profileBody} />
          </button>
        </nav>
      </header>

      <main className="npi-main">
        <section className="npi-hero" aria-labelledby="npi-page-title">
          <img
            className="npi-hero-reference-image"
            src={PARTNER_HERO_REFERENCE_IMAGE}
            alt="제휴문의 파트너십 안내"
            draggable="false"
          />
          <span
            className="npi-hero-reference-text-fix npi-hero-reference-partner-line"
            aria-hidden="true"
          >
            NORA와 파트너가 되어주세요.
          </span>
          <span
            className="npi-hero-reference-text-fix npi-hero-reference-description-line"
            aria-hidden="true"
          >
            NORA는 항상 열린 마음으로 좋은 파트너를 기다리고 있습니다.
          </span>
          <div className="npi-hero-shade" aria-hidden="true" />

          <div className="npi-hero-copy">
            <p className="npi-kicker">PARTNERSHIP WITH NORA</p>
            <h1 id="npi-page-title">제휴문의</h1>
            <h2>
              함께 만들어가는 더 특별한 내일,
              <br />
              <span>NORA와 파트너가 되어주세요.</span>
            </h2>
            <p className="npi-hero-description">
              신뢰와 전문성을 바탕으로, 더 많은 고객과 더 큰 가치를 만들어갑니다.
              <br />
              NORA는 항상 열린 마음으로 좋은 파트너를 기다리고 있습니다.
            </p>
          </div>

          <div className="npi-hero-photo" aria-hidden="true">
            <img src={PARTNER_HERO_IMAGE} alt="" draggable="false" />
          </div>

          <div className="npi-hero-slogan" aria-label="좋은 파트너십, 더 밝은 내일">
            <span className="npi-slogan-line" />
            <strong>GOOD</strong>
            <strong>PARTNERSHIP</strong>
            <strong>BRIGHTER</strong>
            <strong>TOMORROW</strong>
            <small>함께, 더 멀리</small>
          </div>

          <div className="npi-hero-benefits">
            <article>
              <Icon name="bolt" size={37} />
              <div><strong>브랜드 노출</strong><span>NORA의 프리미엄 플랫폼을<br />통한 강력한 브랜드 홍보</span></div>
            </article>
            <article>
              <Icon name="user" size={37} />
              <div><strong>회원 유입</strong><span>검증된 회원 데이터 기반<br />안정적인 고객 유입</span></div>
            </article>
            <article>
              <Icon name="chart" size={37} />
              <div><strong>예약 전환</strong><span>효율적인 매칭 시스템으로<br />높은 예약 전환율</span></div>
            </article>
            <article>
              <Icon name="headset" size={37} />
              <div><strong>운영 지원</strong><span>전담 매니저의<br />지속적인 운영 지원</span></div>
            </article>
          </div>
        </section>

        <section className="npi-content-grid">
          <form id="nora-partner-form" className="npi-panel npi-form-panel" onSubmit={handleSubmit}>
            <div className="npi-panel-heading">
              <div className="npi-heading-copy">
                <span className="npi-heading-icon"><Icon name="file" size={29} /></span>
                <div>
                  <h2>제휴 문의하기</h2>
                  <p>아래 정보를 입력해주시면, 빠르고 친절하게 답변드리겠습니다.</p>
                </div>
              </div>
              <small>모든 항목은 필수는 아니지만, 정확한 상담을 위해 최대한 입력해주세요.</small>
            </div>

            <div className="npi-form-grid">
              <label className="npi-field">
                <span>업체명 <b>*</b></span>
                <input
                  value={form.companyName}
                  onChange={(event) => updateField("companyName", event.target.value)}
                  placeholder="업체명을 입력해주세요."
                  maxLength={80}
                />
              </label>

              <label className="npi-field">
                <span>담당자명 <b>*</b></span>
                <input
                  value={form.managerName}
                  onChange={(event) => updateField("managerName", event.target.value)}
                  placeholder="담당자명을 입력해주세요."
                  maxLength={50}
                />
              </label>

              <label className="npi-field">
                <span>전화번호 <b>*</b></span>
                <input
                  value={form.phone}
                  onChange={(event) => updateField("phone", event.target.value)}
                  placeholder="010-1234-5678"
                  inputMode="tel"
                  maxLength={30}
                />
              </label>

              <label className="npi-field">
                <span>희망 카테고리</span>
                <select value={form.businessType} onChange={(event) => updateField("businessType", event.target.value)}>
                  <option value="">카테고리를 선택해주세요.</option>
                  {BUSINESS_OPTIONS.map((item) => (
                    <option key={item} value={item}>{item}</option>
                  ))}
                </select>
              </label>

              <label className="npi-field npi-region-field">
                <span>지역</span>
                <select value={form.region} onChange={(event) => updateField("region", event.target.value)}>
                  <option value="">지역을 선택해주세요.</option>
                  {REGION_OPTIONS.map((region) => (
                    <option key={region} value={region}>{region}</option>
                  ))}
                </select>
              </label>


              <label className="npi-field npi-message-field">
                <span>문의 내용 <b>*</b></span>
                <span className="npi-textarea-wrap">
                  <textarea
                    value={form.message}
                    onChange={(event) => updateField("message", event.target.value)}
                    placeholder="제휴에 대해 궁금한 내용을 자세히 입력해주세요."
                    maxLength={1000}
                  />
                  <small>{form.message.length} / 1000</small>
                </span>
              </label>
            </div>

            {notice ? (
              <div className={noticeType === "error" ? "npi-notice is-error" : "npi-notice is-info"}>
                {notice}
              </div>
            ) : null}

            <button type="submit" className="npi-submit">
              <Icon name="send" size={23} />
              <span>제휴 신청하기</span>
              <b>›</b>
            </button>
          </form>

          <div className="npi-right-column">
            <section className="npi-panel npi-stats-panel">
              <div className="npi-mini-heading">
                <div><Icon name="star" size={25} /><h2>NORA 파트너십</h2></div>
                <strong>신뢰가 만드는 더 큰 가치</strong>
              </div>
              <p>성공적인 비즈니스를 위한 최적의 파트너, NORA와 함께하세요.</p>
              <div className="npi-stat-grid">
                <article><Icon name="user" size={30} /><strong>50,000+</strong><span>누적 회원 수</span></article>
                <article><Icon name="building" size={30} /><strong>1,200+</strong><span>제휴 업체</span></article>
                <article><Icon name="chart" size={30} /><strong>92%</strong><span>고객 만족도</span></article>
                <article><Icon name="diamond" size={30} /><strong>NO.1</strong><span>프리미엄 플랫폼</span></article>
              </div>
            </section>

            <section className="npi-panel npi-process-panel">
              <div className="npi-mini-heading">
                <div><Icon name="star" size={23} /><h2>제휴 진행 절차</h2></div>
                <small>간단한 절차로 빠르게 시작하세요.</small>
              </div>
              <div className="npi-process-grid">
                <article><b>01</b><Icon name="file" size={28} /><strong>문의 접수</strong><span>온라인 문의 신청<br />(24시간 접수)</span></article>
                <i>›</i>
                <article><b>02</b><Icon name="user" size={28} /><strong>담당자 상담</strong><span>1:1 맞춤 상담<br />(평일 1일 이내)</span></article>
                <i>›</i>
                <article><b>03</b><Icon name="file" size={28} /><strong>제휴 조건 협의</strong><span>세부 조건 조율<br />(맞춤 제안)</span></article>
                <i>›</i>
                <article><b>04</b><Icon name="check" size={28} /><strong>제휴 완료</strong><span>계약 진행 및<br />서비스 오픈</span></article>
              </div>
            </section>

            <section className="npi-panel npi-contact-panel">
              <div className="npi-contact-help">
                <span><Icon name="phone" size={24} /></span>
                <div><strong>빠른 상담 안내</strong><p>더 궁금한 점이 있으신가요?<br />지금 바로 전문가와 상담하세요.</p></div>
              </div>
              <div className="npi-contact-number">
                <span>대표 제휴문의</span>
                <a href="tel:010-1234-5678">010-1234-5678</a>
                <small>평일 09:00 ~ 18:00 (주말·공휴일 휴무)</small>
              </div>
            </section>
          </div>
        </section>

        <section className="npi-bottom-banner" aria-label="좋은 파트너십이 더 나은 내일을 만듭니다.">
          <img
            className="npi-bottom-banner-image"
            src={PARTNER_BOTTOM_BANNER_IMAGE}
            alt="좋은 파트너십이 더 나은 내일을 만듭니다. NORA는 언제나 새로운 가능성을 열어두고 있습니다."
            draggable="false"
          />
          <span className="npi-bottom-banner-brandline" aria-hidden="true">
            NORA는 언제나 새로운 가능성을 열어두고 있습니다.
          </span>
        </section>
      </main>
    </div>
  );
}

const PARTNER_RESPONSIVE_CSS = `
  .nora-partner-root,
  .nora-partner-root * {
    box-sizing: border-box;
  }

  .nora-partner-root {
    --gold-light: #F7D774;
    --gold: #D4AF37;
    --gold-dark: #B8860B;
    --gold-gradient: linear-gradient(90deg, #F7D774 0%, #D4AF37 50%, #B8860B 100%);
    --panel-border: rgba(212, 175, 55, .58);
    --panel-bg: #060606;
    overflow-x: hidden;
    background: #000;
    text-rendering: optimizeLegibility;
    font-kerning: normal;
    font-synthesis: none;
  }

  .nora-partner-root button,
  .nora-partner-root input,
  .nora-partner-root select,
  .nora-partner-root textarea {
    font: inherit;
  }

  /* -------------------------------------------------------
     REFERENCE DESKTOP CANVAS
     Right reference: 1668px wide, content about 54px each side.
     Keep the same 54px desktop gutter so widths/spacing line up.
     ------------------------------------------------------- */
  .npi-main {
    width: min(calc(100% - 108px), 1800px);
    margin: 0 auto 8px;
    padding-top: 0;
    color: #fff;
    font-family: Pretendard, "Noto Sans KR", "Malgun Gothic", sans-serif;
  }

  .npi-panel,
  .npi-bottom-banner {
    border: 1px solid transparent;
    background:
      linear-gradient(#070707, #070707) padding-box,
      var(--gold-gradient) border-box;
  }

  /* ========================= HERO ========================= */
  .npi-hero {
    position: relative;
    height: 278px;
    overflow: hidden;
    border: 0;
    border-radius: 0;
    background: #050505;
  }

  .npi-hero::before {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 1;
    background:
      linear-gradient(90deg,
        rgba(0,0,0,.98) 0%,
        rgba(0,0,0,.94) 20%,
        rgba(0,0,0,.62) 34%,
        rgba(0,0,0,.10) 52%,
        rgba(0,0,0,.12) 76%,
        rgba(0,0,0,.78) 90%,
        rgba(0,0,0,.97) 100%),
      linear-gradient(180deg,
        rgba(0,0,0,.02) 0%,
        rgba(0,0,0,.02) 56%,
        rgba(0,0,0,.66) 79%,
        rgba(0,0,0,.96) 100%);
    pointer-events: none;
  }

  .npi-hero::after {
    content: "";
    position: absolute;
    inset: 0;
    z-index: 2;
    opacity: .34;
    background:
      radial-gradient(circle at 54% 17%, rgba(247,215,116,.18), transparent 21%),
      linear-gradient(115deg, transparent 0 28%, rgba(212,175,55,.07) 43%, transparent 57% 100%);
    pointer-events: none;
  }

  .npi-hero-shade {
    position: absolute;
    inset: 0;
    z-index: 3;
    pointer-events: none;
    background:
      linear-gradient(90deg, rgba(0,0,0,.20), transparent 30% 72%, rgba(0,0,0,.34));
  }

  .npi-hero-photo {
    position: absolute;
    inset: 0;
    z-index: 0;
    overflow: hidden;
    background: #080706;
  }

  .npi-hero-photo img {
    width: 100%;
    height: 100%;
    display: block;
    object-fit: cover;
    object-position: center 58%;
    transform: none;
    filter: brightness(.61) contrast(1.20) saturate(.62) sepia(.30);
    user-select: none;
    pointer-events: none;
  }

  .npi-hero-copy {
    position: relative;
    z-index: 5;
    width: 455px;
    padding: 15px 0 0 20px;
    opacity: 1;
    filter: none;
  }

  .npi-kicker {
    margin: 0;
    width: fit-content;
    background: none;
    color: #D4AF37;
    -webkit-text-fill-color: #D4AF37;
    font-family: Georgia, "Times New Roman", serif;
    font-size: 13px;
    font-weight: 800;
    line-height: 1;
    letter-spacing: 3.2px;
    text-shadow: none;
  }

  .npi-hero-copy h1 {
    width: fit-content;
    margin: 12px 0 0;
    background: none;
    color: #F7D774;
    -webkit-text-fill-color: #F7D774;
    font-family: "Noto Serif KR", "Nanum Myeongjo", Georgia, serif;
    font-size: 47px;
    font-weight: 800;
    line-height: 1.04;
    letter-spacing: -3px;
    text-shadow: none;
  }

  .npi-hero-copy h2 {
    margin: 14px 0 0;
    color: #F7D774;
    -webkit-text-fill-color: #F7D774;
    font-family: "Noto Serif KR", "Nanum Myeongjo", Georgia, serif;
    font-size: 24px;
    font-weight: 700;
    line-height: 1.42;
    letter-spacing: -1px;
    text-shadow: none;
  }

  .npi-hero-copy h2 span {
    background: none;
    color: #F7D774;
    -webkit-text-fill-color: #F7D774;
    text-shadow: none;
  }

  .npi-hero-description {
    margin: 16px 0 0;
    color: #F4F4F4;
    font-size: 12px;
    font-weight: 600;
    line-height: 1.65;
    text-shadow: none;
  }

  .npi-hero-slogan {
    position: absolute;
    z-index: 5;
    top: 25px;
    right: 20px;
    width: 172px;
    display: flex;
    flex-direction: column;
    align-items: center;
    background: transparent;
    color: #F7D774;
    font-family: Georgia, "Times New Roman", serif;
    text-align: center;
    opacity: 1;
    filter: none;
  }

  .npi-slogan-line {
    width: 42px;
    height: 1px;
    margin: 0 0 22px auto;
    align-self: flex-end;
    background: var(--gold-gradient);
  }

  .npi-hero-slogan strong {
    width: fit-content;
    background: none;
    color: #F7D774;
    -webkit-text-fill-color: #F7D774;
    font-size: 17px;
    font-weight: 800;
    line-height: 1.16;
    letter-spacing: .8px;
    text-shadow: none;
  }

  .npi-hero-slogan small {
    margin-top: 15px;
    color: #F2F2F2;
    font-family: Pretendard, "Noto Sans KR", sans-serif;
    font-size: 8px;
    font-weight: 600;
    text-shadow: none;
  }

  .npi-hero-benefits {
    position: absolute;
    z-index: 6;
    right: 19px;
    bottom: 0;
    width: 70.2%;
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 12px;
    opacity: 1;
    filter: none;
  }

  .npi-hero-benefits article {
    min-width: 0;
    height: 87px;
    display: flex;
    align-items: center;
    gap: 18px;
    padding: 10px 22px;
    border: 1px solid transparent;
    border-radius: 3px;
    background:
      linear-gradient(135deg, rgba(18,17,14,.95), rgba(5,5,5,.97)) padding-box,
      var(--gold-gradient) border-box;
    color: #F7D774;
  }

  .npi-hero-benefits article > div {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 5px;
  }

  .npi-hero-benefits strong {
    color: #FFFFFF;
    font-size: 16px;
    font-weight: 850;
    line-height: 1.15;
    white-space: nowrap;
    text-shadow: none;
  }

  .npi-hero-benefits span {
    color: #F0F0F0;
    font-size: 10px;
    font-weight: 600;
    line-height: 1.42;
    text-shadow: none;
  }

  /* ======================= LOWER GRID ====================== */
  .npi-content-grid {
    display: grid;
    grid-template-columns: minmax(0, 1.116fr) minmax(0, 1fr);
    gap: 12px;
    margin-top: 18px;
  }

  .npi-panel {
    border-radius: 3px;
    background:
      radial-gradient(circle at 100% 0%, rgba(212,175,55,.045), transparent 22%) padding-box,
      linear-gradient(145deg, #090909, #050505 72%) padding-box,
      var(--gold-gradient) border-box;
  }

  /* ========================= FORM ========================== */
  .npi-form-panel {
    min-height: 480px;
    padding: 15px 20px 14px;
    display: flex;
    flex-direction: column;
  }

  .npi-panel-heading,
  .npi-mini-heading {
    display: flex;
    align-items: flex-start;
    justify-content: space-between;
    gap: 16px;
  }

  .npi-panel-heading {
    min-height: 57px;
    padding: 0 0 11px;
    border-bottom: 1px solid #252525;
  }

  .npi-heading-copy,
  .npi-mini-heading > div {
    display: flex;
    align-items: center;
    gap: 12px;
  }

  .npi-heading-icon {
    width: 37px;
    height: 37px;
    display: grid;
    place-items: center;
    flex: 0 0 auto;
    color: #D4AF37;
    background: rgba(212,175,55,.07);
  }

  .npi-panel-heading h2,
  .npi-mini-heading h2 {
    margin: 0;
    color: #fff;
    font-size: 20px;
    font-weight: 850;
    line-height: 1.1;
    letter-spacing: -.7px;
  }

  .npi-panel-heading p,
  .npi-stats-panel > p {
    margin: 5px 0 0;
    color: #bebebe;
    font-size: 10px;
    font-weight: 400;
    line-height: 1.4;
  }

  .npi-panel-heading > small {
    align-self: center;
    color: #b8b8b8;
    font-size: 9px;
    font-weight: 400;
    line-height: 1.45;
    text-align: right;
  }

  .npi-form-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    grid-template-rows: repeat(3, 50px) minmax(126px, 1fr);
    gap: 14px 20px;
    margin-top: 14px;
    flex: 1 1 auto;
    min-height: 0;
  }

  .npi-field {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 7px;
  }

  .npi-field:not(.npi-message-field) {
    display: grid;
    grid-template-columns: 90px minmax(0, 1fr);
    align-items: center;
    column-gap: 14px;
  }

  .npi-field > span:first-child {
    color: #ffffff;
    font-size: 13px;
    font-weight: 850;
    line-height: 1.2;
    letter-spacing: -.2px;
  }

  .npi-field:not(.npi-message-field) > span:first-child {
    white-space: nowrap;
  }

  .npi-field b {
    background: var(--gold-gradient);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
  }

  .npi-field input,
  .npi-field select,
  .npi-field textarea {
    width: 100%;
    min-width: 0;
    border: 1px solid #3d3d3d;
    border-radius: 4px;
    outline: none;
    background: linear-gradient(180deg, #1b1d1f, #121416);
    color: #ffffff;
    font-size: 13px;
    font-weight: 600;
    transition: border-color .18s ease, box-shadow .18s ease;
  }

  .npi-field input,
  .npi-field select {
    height: 50px;
    padding: 0 16px;
  }

  .npi-field textarea {
    height: 100%;
    min-height: 118px;
    padding: 14px 16px 28px;
    resize: vertical;
    line-height: 1.5;
  }

  .npi-field input:focus,
  .npi-field select:focus,
  .npi-field textarea:focus {
    border-color: #D4AF37;
    box-shadow: 0 0 0 2px rgba(212,175,55,.09);
  }

  .npi-field input::placeholder,
  .npi-field textarea::placeholder {
    color: #8b8b8b;
  }

  .npi-field select {
    color-scheme: dark;
  }

  .npi-field select option {
    background: #101010;
    color: #fff;
  }

  .npi-region-field {
    grid-column: 1 / -1;
  }

  .npi-message-field {
    grid-column: 1 / -1;
    min-height: 0;
  }

  .npi-textarea-wrap {
    position: relative;
    display: block;
    flex: 1 1 auto;
    min-height: 0;
  }

  .npi-textarea-wrap small {
    position: absolute;
    right: 9px;
    bottom: 7px;
    color: #d7d7d7;
    font-size: 8px;
  }

  .npi-notice {
    margin-top: 7px;
    padding: 7px 10px;
    border-radius: 4px;
    font-size: 10px;
  }

  .npi-notice.is-error {
    border: 1px solid #743737;
    background: #210b0b;
    color: #ffb5b5;
  }

  .npi-notice.is-info {
    border: 1px solid rgba(212,175,55,.45);
    background: rgba(212,175,55,.08);
    color: #f0cf75;
  }

  .npi-submit {
    width: 100%;
    height: 50px;
    margin-top: 14px;
    display: grid;
    grid-template-columns: 27px 1fr 20px;
    align-items: center;
    padding: 0 20px;
    border: 1px solid #F7D774;
    border-radius: 4px;
    background: var(--gold-gradient);
    color: #151005;
    cursor: pointer;
    font-size: 15px;
    font-weight: 900;
    box-shadow: inset 0 1px 0 rgba(255,255,255,.38), 0 4px 14px rgba(184,134,11,.11);
  }

  .npi-submit span { text-align: center; }
  .npi-submit b { font-size: 25px; font-weight: 400; }

  .npi-form-grid + .npi-submit,
  .npi-notice + .npi-submit {
    margin-bottom: 0;
  }

  /* ====================== RIGHT COLUMN ===================== */
  .npi-right-column {
    min-width: 0;
    display: grid;
    grid-template-rows: 192px 166px 102px;
    gap: 10px;
  }

  .npi-stats-panel,
  .npi-process-panel,
  .npi-contact-panel {
    min-width: 0;
  }

  .npi-stats-panel {
    padding: 15px 18px 13px;
  }

  .npi-process-panel {
    padding: 13px 18px 12px;
  }

  .npi-mini-heading {
    align-items: center;
  }

  .npi-mini-heading > div {
    color: #D4AF37;
  }

  .npi-mini-heading > strong {
    width: fit-content;
    background: var(--gold-gradient);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    font-size: 9px;
    font-weight: 800;
  }

  .npi-mini-heading > small {
    color: #bdbdbd;
    font-size: 8px;
  }

  .npi-stat-grid {
    display: grid;
    grid-template-columns: repeat(4, minmax(0, 1fr));
    gap: 10px;
    margin-top: 13px;
  }

  .npi-stat-grid article {
    height: 102px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 4px;
    border: 1px solid transparent;
    border-radius: 3px;
    background:
      linear-gradient(rgba(7,7,7,.90), rgba(7,7,7,.90)) padding-box,
      var(--gold-gradient) border-box;
    color: #D4AF37;
  }

  .npi-stat-grid strong {
    margin-top: 1px;
    background: var(--gold-gradient);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    font-size: 22px;
    font-weight: 950;
    line-height: 1.05;
  }

  .npi-stat-grid span {
    color: #fff;
    font-size: 9px;
    font-weight: 700;
  }

  .npi-process-grid {
    display: grid;
    grid-template-columns: 1fr 18px 1fr 18px 1fr 18px 1fr;
    align-items: center;
    margin-top: 11px;
  }

  .npi-process-grid article {
    position: relative;
    height: 108px;
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 3px;
    border: 1px solid #2d2d2d;
    background: rgba(6,6,6,.86);
    color: #D4AF37;
    text-align: center;
  }

  .npi-process-grid article > b {
    position: absolute;
    top: 7px;
    left: 7px;
    width: 25px;
    height: 25px;
    display: grid;
    place-items: center;
    border-radius: 50%;
    background: var(--gold-gradient);
    color: #151005;
    font-size: 9px;
  }

  .npi-process-grid article > strong {
    margin-top: 3px;
    color: #fff;
    font-size: 11px;
    line-height: 1.15;
  }

  .npi-process-grid article > span {
    color: #cfcfcf;
    font-size: 8px;
    line-height: 1.4;
  }

  .npi-process-grid > i {
    background: var(--gold-gradient);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    font-family: Georgia, serif;
    font-size: 23px;
    font-style: normal;
    text-align: center;
  }

  .npi-contact-panel {
    min-height: 102px;
    display: grid;
    grid-template-columns: 1fr 1fr;
    align-items: stretch;
    padding: 8px 10px;
  }

  .npi-contact-help,
  .npi-contact-number {
    display: flex;
    align-items: center;
    gap: 11px;
    padding: 4px 12px;
    border-right: 1px solid #282828;
  }

  .npi-contact-help > span {
    width: 34px;
    height: 34px;
    display: grid;
    place-items: center;
    flex: 0 0 auto;
    border-radius: 3px;
    background: var(--gold-gradient);
    color: #171005;
  }

  .npi-contact-help strong,
  .npi-contact-number > span {
    color: #fff;
    font-size: 11px;
  }

  .npi-contact-help p {
    margin: 4px 0 0;
    color: #c7c7c7;
    font-size: 9px;
    line-height: 1.4;
  }

  .npi-contact-number {
    flex-direction: column;
    align-items: flex-start;
    justify-content: center;
    gap: 2px;
    border-right: 0;
  }

  .npi-contact-number a {
    background: var(--gold-gradient);
    -webkit-background-clip: text;
    background-clip: text;
    color: transparent;
    font-size: 18px;
    font-weight: 900;
    line-height: 1.1;
    text-decoration: none;
  }

  .npi-contact-number small {
    color: #a5a5a5;
    font-size: 7px;
    white-space: nowrap;
  }

  .npi-contact-actions {
    display: grid;
    grid-template-rows: 1fr 1fr;
    gap: 6px;
    padding-left: 11px;
  }

  .npi-contact-actions button {
    display: grid;
    grid-template-columns: 21px 1fr 14px;
    align-items: center;
    gap: 6px;
    padding: 0 11px;
    border: 1px solid transparent;
    border-radius: 4px;
    background:
      linear-gradient(#0d0d0d, #0d0d0d) padding-box,
      var(--gold-gradient) border-box;
    color: #fff;
    cursor: pointer;
    font-size: 10px;
    font-weight: 800;
  }

  .npi-contact-actions button:first-child {
    background: var(--gold-gradient);
    color: #161005;
  }

  .npi-contact-actions button b {
    font-size: 18px;
    font-weight: 400;
  }

  /* ======================= BOTTOM BANNER =================== */
  .npi-bottom-banner {
    position: relative;
    width: 100vw;
    min-height: 0;
    margin: 13px 0 0 calc(50% - 50vw);
    padding: 0;
    overflow: hidden;
    border: 0;
    border-radius: 0;
    background: #000;
  }

  .npi-bottom-banner::after {
    content: none;
  }

  .npi-bottom-banner-image {
    display: block;
    width: 100%;
    height: auto;
    margin: 0;
    padding: 0;
    border: 0;
    object-fit: contain;
    object-position: center;
    user-select: none;
    pointer-events: none;
  }

  /* The reference banner image contains the old brand name in its small
     subtitle. Keep the image itself unchanged and cover only that subtitle
     with the current NORA wording. */
  .npi-bottom-banner-brandline {
    position: absolute;
    z-index: 2;
    left: 9.35%;
    top: 52.5%;
    width: 27.5%;
    height: 22%;
    display: flex;
    align-items: center;
    margin: 0;
    padding: 0;
    background: linear-gradient(
      90deg,
      rgba(8, 7, 5, .995) 0%,
      rgba(8, 7, 5, .995) 82%,
      rgba(8, 7, 5, 0) 100%
    );
    color: #b9b9b9;
    font-family: Pretendard, "Noto Sans KR", "Malgun Gothic", sans-serif;
    font-size: clamp(8px, .68vw, 12px);
    font-weight: 500;
    line-height: 1;
    letter-spacing: 0;
    white-space: nowrap;
    pointer-events: none;
    user-select: none;
  }

  @media (hover: hover) {
    .npi-submit:hover,
    .npi-contact-actions button:hover {
      filter: brightness(1.07);
    }

    .npi-hero-benefits article:hover,
    .npi-stat-grid article:hover {
      box-shadow: inset 0 0 0 1px rgba(247,215,116,.18);
    }
  }

  /* Full-bleed desktop hero: the reference hero touches both viewport edges.
     Lower panels keep the existing 54px content gutter. */
  @media (min-width: 1451px) {
    .npi-hero {
      width: 100vw;
      margin-left: calc(50% - 50vw);
    }

    .npi-hero-copy {
      padding-left: 74px;
    }

    .npi-hero-slogan {
      right: 74px;
    }

    .npi-hero-benefits {
      right: 73px;
      width: 65.65vw;
      max-width: 1182px;
    }
  }

  /* 1668px reference keeps exact desktop ratios. */
  @media (max-width: 1450px) {
    .npi-main { width: min(calc(100% - 44px), 1800px); }
    .npi-hero-copy { width: 430px; }
    .npi-hero-benefits { width: 71.5%; gap: 8px; right: 14px; }
    .npi-hero-benefits article { padding: 9px 13px; gap: 10px; }
    .npi-hero-slogan { right: 12px; width: 155px; }
    .npi-contact-panel { grid-template-columns: 1fr 1fr; height: auto; }
    .npi-contact-actions { grid-column: 1 / -1; grid-template-columns: 1fr 1fr; grid-template-rows: 36px; padding: 7px 0 0; }
    .npi-right-column { grid-template-rows: auto auto auto; }
  }

  @media (max-width: 1180px) {
    .npi-main { margin-top: 0; }
    .npi-form-grid { flex: 0 0 auto; grid-template-rows: none; }
    .npi-hero { height: auto; min-height: 610px; }
    .npi-hero-photo { height: 300px; }
    .npi-hero-photo img { object-position: center 50%; }
    .npi-hero-benefits { left: 18px; right: 18px; bottom: 16px; width: auto; grid-template-columns: 1fr 1fr; }
    .npi-hero-benefits article { height: 82px; }
    .npi-hero-slogan { display: none; }
    .npi-content-grid { grid-template-columns: 1fr; }
    .npi-right-column { grid-template-rows: auto; }
    .npi-form-panel { min-height: 0; }
  }

  @media (max-width: 820px) {
    .nora-jobs-page-header { position: relative !important; padding: 10px 14px !important; }
    .nora-jobs-page-nav { gap: 6px !important; transform: none !important; }
    .nora-jobs-page-nav button { min-height: 38px !important; padding: 0 11px !important; font-size: 12px !important; }
    .npi-main { width: calc(100% - 20px); }
    .npi-hero { min-height: 720px; }
    .npi-hero-copy { width: auto; padding: 21px 18px; }
    .npi-hero-copy h1 { font-size: 43px; }
    .npi-hero-copy h2 { font-size: 20px; }
    .npi-hero-photo { top: 225px; height: 220px; }
    .npi-hero-benefits { grid-template-columns: 1fr; }
    .npi-hero-benefits article { height: 72px; }
    .npi-panel-heading { flex-direction: column; }
    .npi-panel-heading > small { text-align: left; }
    .npi-form-grid { grid-template-columns: 1fr; }
    .npi-field:not(.npi-message-field) { grid-template-columns: 1fr; gap: 7px; }
    .npi-region-field, .npi-message-field { grid-column: auto; }
    .npi-stat-grid { grid-template-columns: 1fr 1fr; }
    .npi-process-grid { grid-template-columns: 1fr 1fr; gap: 8px; }
    .npi-process-grid > i { display: none; }
    .npi-contact-panel { grid-template-columns: 1fr; }
    .npi-contact-help, .npi-contact-number { border-right: 0; border-bottom: 1px solid #292929; }
    .npi-contact-actions { grid-column: auto; grid-template-columns: 1fr; grid-template-rows: 38px 38px; }
  }

  @media (max-width: 520px) {
    .nora-jobs-page-header { align-items: flex-start !important; }
    .npi-main { width: calc(100% - 12px); }
    .npi-hero { min-height: 748px; }
    .npi-kicker { font-size: 10px; letter-spacing: 2px; }
    .npi-hero-copy h1 { font-size: 38px; }
    .npi-hero-copy h2 { font-size: 17px; }
    .npi-hero-description { font-size: 10px; }
    .npi-form-panel, .npi-stats-panel, .npi-process-panel { padding: 13px 11px; }
    .npi-stat-grid { gap: 7px; }
    .npi-process-grid { grid-template-columns: 1fr; }
    .npi-contact-actions { grid-template-columns: 1fr; }
  }

  /* Exact user-provided reference hero image: preserve original pixels/aspect ratio. */
  .npi-hero {
    height: auto !important;
    min-height: 0 !important;
    overflow: hidden;
    border: 0 !important;
    background: #000;
  }

  .npi-hero-reference-image {
    position: relative;
    z-index: 20;
    display: block;
    width: 100%;
    height: auto;
    max-width: none;
    object-fit: contain;
    object-position: center;
    user-select: none;
    pointer-events: none;
  }

  .npi-hero-reference-text-fix {
    position: absolute;
    z-index: 30;
    display: flex;
    align-items: center;
    margin: 0;
    padding: 0;
    overflow: hidden;
    pointer-events: none;
    user-select: none;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    text-rendering: geometricPrecision;
  }

  .npi-hero-reference-partner-line {
    left: 4.42%;
    top: 49.65%;
    width: 24.4%;
    height: 12.6%;
    padding-left: .02%;
    background: linear-gradient(
      90deg,
      rgba(3, 3, 3, .995) 0%,
      rgba(4, 4, 4, .985) 92%,
      rgba(4, 4, 4, 0) 100%
    );
    color: #F7D774;
    font-family: "Noto Serif KR", "Nanum Myeongjo", Georgia, "Times New Roman", serif;
    font-size: clamp(17px, 1.29vw, 24px);
    font-weight: 700;
    line-height: 1;
    letter-spacing: -.8px;
    white-space: nowrap;
    text-shadow: 0 0 .25px rgba(247, 215, 116, .55);
  }

  .npi-hero-reference-description-line {
    left: 4.42%;
    top: 75.25%;
    width: 25.6%;
    height: 9.4%;
    padding-left: .02%;
    background: linear-gradient(
      90deg,
      rgba(3, 3, 3, .995) 0%,
      rgba(4, 4, 4, .985) 92%,
      rgba(4, 4, 4, 0) 100%
    );
    color: #d8d8d8;
    font-family: Pretendard, "Noto Sans KR", "Malgun Gothic", sans-serif;
    font-size: clamp(9px, .64vw, 12px);
    font-weight: 500;
    line-height: 1;
    letter-spacing: -.12px;
    white-space: nowrap;
  }

  .npi-hero > :not(.npi-hero-reference-image):not(.npi-hero-reference-text-fix) {
    display: none !important;
  }
`;

